import type { ReactNode } from 'react';

/**
 * Metadata for this segment is generated by page.tsx, which can resolve both
 * bundled articles and live CMS posts. Keeping the layout free of a second
 * generateMetadata avoids stale titles for CMS-published slugs.
 */
export default function RouteLayout({ children }: { children: ReactNode }) {
  return children;
}
